            ErrorMaskBuilder? errorMask,
            TranslationCrystal? copyMask,
            bool deepCopy)
        {
            try
            {
                DeepCopyInInternal(
                    item: item,
                    rhs: rhs,
                    errorMask: errorMask,
                    copyMask: copyMask,
                    deepCopy: deepCopy);
            }
            catch (Exception ex)
            {
