                            errorMask: errorMask,
                            copyMask?.GetSubCrystal((int)Challenge_FieldIndex.Icons));
                    }
                    else
                    {
                        item.Icons = default;
                    }
                }
                catch (Exception ex)
                when (errorMask != null)
                {
                    errorMask.ReportException(ex);
                }
                finally
                {
                    errorMask?.PopIndex();
                }
            }
            if ((copyMask?.GetShouldTranslate((int)Challenge_FieldIndex.Script) ?? true))
            {
                item.Script.SetTo(rhs.Script.FormKeyNullable);
            }
            if ((copyMask?.GetShouldTranslate((int)Challenge_FieldIndex.Description) ?? true))
            {
                item.Description = rhs.Description;
            }
            if ((copyMask?.GetShouldTranslate((int)Challenge_FieldIndex.Type) ?? true))
            {
