            if ((copyMask?.GetShouldTranslate((int)Challenge_FieldIndex.Flags) ?? true))
            {
                item.Flags = rhs.Flags;
            }
            if ((copyMask?.GetShouldTranslate((int)Challenge_FieldIndex.Interval) ?? true))
            {
                item.Interval = rhs.Interval;
            }
            if ((copyMask?.GetShouldTranslate((int)Challenge_FieldIndex.TypeData) ?? true))
            {
                item.TypeData = rhs.TypeData.ToArray();
